import React from 'react';
import { Link as RouterLink } from 'react-router-dom';
import {
  Box,
  Container,
  FormControl,
  FormHelperText,
  Grid,
  IconButton,
  // Input,
  InputAdornment,
  InputLabel,
  Link,
  OutlinedInput,
  // TextField,
  Typography,
} from '@material-ui/core';
// import FacebookIcon from 'src/icons/Facebook';
// import GoogleIcon from 'src/icons/Google';
import { connect } from 'react-redux';
import { login } from 'actions/admin/auth';
import Validator from 'validator';
import { MSG } from 'shared/common/languages/english';
import Card from '@material-ui/core/Card';
// import CardActions from '@material-ui/core/CardActions';
import CardContent from '@material-ui/core/CardContent';
import CustomButton from '../../../components/CustomButton.jsx';
import {
  getGlobalCurrentBatchUtils,
  removeLocalStoreItem,
  getCurrentYearBatchUtils,
  formResMessage,
} from '../../../utils/commonFunc.js';
import colors from '../../../config/colors.js';
import { isLandingHost, LANDING_SITE_URL } from '../../../config/domainContent.js';
import Logo from '../../../theme/Logo';
import { Form } from 'reactstrap';
import { fetchCurrentBatchByYearService } from 'actions/admin/batches.js';
import { fetchSchoolService } from 'actions/admin/schools.js';
import { Visibility, VisibilityOff } from '@material-ui/icons';

const initialState = {
  data: {
    username: '',
    password: '',
  },
  errors: {},
  loading: false,
  showPassword: false,
};
let timer;
class LoginPage extends React.Component {
  state = initialState;

  componentDidMount() {
    removeLocalStoreItem('loggedUser');
    removeLocalStoreItem('globalSchool');
    removeLocalStoreItem('currentBatch');
    removeLocalStoreItem('actualCurrentBatch');
  }

  loginSuccess = () => {
    timer = setTimeout(() => {
      this.props.history.push('/admin/dashboard');
    }, 500);
  };

  handleChange = e => {
    this.setState({
      data: {
        ...this.state.data,
        [e.target.name]: e.target.value,
      },
    });
  };

  // Users may type a bare username ("adminobs") or a full email
  // ("adminobs@school.com"). Only append the default domain when no "@"
  // is already present, so custom domains are left untouched.
  normalizeUsername = username => {
    if (!username) return username;
    const trimmed = username.trim();
    return trimmed.includes('@') ? trimmed : `${trimmed}@gmail.com`;
  };

  validate = data => {
    const errors = {};
    if (Validator.isEmpty(data.username)) {
      errors.username = MSG.email_cannot_empty;
    } else if (!Validator.isEmail(this.normalizeUsername(data.username))) {
      errors.username = MSG.email_invalid;
    }
    if (Validator.isEmpty(data.password)) {
      errors.password = MSG.password_cannot_empty;
    }
    return errors;
  };

  handleSubmit = (e, creds) => {
    e?.preventDefault();
    const { batchId } = getGlobalCurrentBatchUtils();
    const errors = !creds ? this.validate(this.state.data) : {};
    this.setState({ errors });
    if (!Object.keys(errors).length) {
      this.setState({ loading: true });
      const payload = creds || {
        ...this.state.data,
        username: this.normalizeUsername(this.state.data.username),
      };
      return this.props
        .login(payload)
        .then(res => {
          if (res?.schoolId) {
            this.props.fetchSchool({ token: res?.accessToken, schoolId: res?.schoolId });
          }
          if (res && !batchId) {
            const { startYear, endYear } = getCurrentYearBatchUtils();
            if (res?.schoolId) {
              this.props.fetchCurrentBatchByYear({
                token: res?.accessToken,
                schoolId: res?.schoolId,
                startYear,
                endYear,
              });
            }
          }
          this.setState(initialState);
          this.loginSuccess();
        })
        .catch(err => {
          const globalErrors = {
            global: formResMessage(err),
          };
          this.setState({ errors: globalErrors, loading: false });
        });
    }
  };

  componentWillUnmount() {
    if (timer) {
      clearTimeout(timer);
    }
  }

  toggleShowPassword = () => this.setState(prevState => ({ ...prevState, showPassword: !prevState.showPassword }));

  render() {
    const { data, errors, loading, showPassword } = this.state;
    return (
      <>
        <Box
          sx={{
            backgroundColor: 'background.default',
            display: 'flex',
            flexDirection: 'column',
            height: '100%',
            justifyContent: 'center',
            textAlign: 'center',
          }}>
          <Container style={{ padding: 0 }}>
            <Card elevation={0} style={{ color: '#ffffff' }}>
              <CardContent>
                <div style={{ textAlign: 'center', paddingBlock: 20 }}>
                  <Logo />
                </div>
                <Grid item xs={12}>
                  <Grid container style={{ justifyContent: 'center', alignItems: 'center' }}>
                    <Grid item>
                      <Grid>
                        <Typography
                          style={{
                            margin: 0,
                            fontSize: '1.2rem',
                            fontWeight: 600,
                            marginBottom: '0.35em',
                            color: colors.themeColor,
                          }}
                          gutterBottom
                          variant={'h5'}>
                          Welcome Back
                        </Typography>
                      </Grid>
                    </Grid>
                  </Grid>
                </Grid>
                <Form onSubmit={this.handleSubmit}>
                  {errors.global && (
                    <Typography
                      className="alert alert-danger text-center"
                      style={{
                        borderRadius: '3px',
                        padding: '10px',
                        width: '100%',
                        boxSizing: 'border-box',
                        marginTop: 10,
                      }}>
                      {errors?.global}
                    </Typography>
                  )}
                  <FormControl variant="outlined" fullWidth error={Boolean(errors.username)} style={{ marginTop: 20 }}>
                    <InputLabel htmlFor="component-outlined">Username or Email</InputLabel>
                    <OutlinedInput
                      error={Boolean(errors.username)}
                      fullWidth
                      label="Username or Email"
                      name="username"
                      onChange={this.handleChange}
                      type="username"
                      value={data.username}
                      variant="outlined"
                      style={{ background: '#F8FAFC', borderRadius: 10 }}
                    />
                    {errors.username && <FormHelperText id="component-error-text">{errors.username}</FormHelperText>}
                  </FormControl>
                  <FormControl variant="outlined" fullWidth error={Boolean(errors.password)} style={{ marginTop: 15 }}>
                    <InputLabel htmlFor="component-outlined">Password</InputLabel>
                    <OutlinedInput
                      error={Boolean(errors.password)}
                      fullWidth
                      name="password"
                      id="component-outlined"
                      type={showPassword ? 'text' : 'password'}
                      value={data.password}
                      onChange={this.handleChange}
                      endAdornment={
                        <InputAdornment position="end">
                          <IconButton
                            aria-label="toggle password visibility"
                            onClick={this.toggleShowPassword}
                            onMouseDown={this.toggleShowPassword}>
                            {showPassword ? <Visibility /> : <VisibilityOff />}
                          </IconButton>
                        </InputAdornment>
                      }
                      label="Password"
                      style={{ background: '#F8FAFC', borderRadius: 10 }}
                    />
                    {errors.password && <FormHelperText id="component-error-text">{errors.password}</FormHelperText>}
                  </FormControl>
                  <Box sx={{ py: 3 }}>
                    <CustomButton
                      size="large"
                      type="submit"
                      variant="contained"
                      color="secondary"
                      name="Sign in"
                      fullWidth
                      loading={loading}
                      disabled={loading}
                      style={{ ...(!loading && { backgroundColor: colors.themeColor, color: '#FFFFFF' }) }}
                    />
                  </Box>
                  <Typography color="textSecondary" variant="body2" style={{ marginBottom: '30px' }}>
                    New to Scholae or need help?{' '}
                    <Link
                      component={RouterLink}
                      to="#"
                      variant="body2"
                      // Full page load on purpose: the landing page's styles (index.js) are only loaded when
                      // the app starts at "/", so a client-side route there would render unstyled.
                      onClick={() =>
                        window.location.assign(isLandingHost() ? '/#contact-us' : `${LANDING_SITE_URL}/#contact-us`)
                      }>
                      Contact us
                    </Link>
                  </Typography>
                  {/* <Box sx={{ py: 1 }}>
                    <Typography color="textSecondary" variant="caption">
                      You can enquire your admission here{' '}
                      <Link
                        component={RouterLink}
                        to="#"
                        variant="caption"
                        onClick={() => this.props.history.push('/admin/admission-enquiry')}>
                        Admission Enquiry
                      </Link>
                    </Typography>
                  </Box> */}
                </Form>
              </CardContent>
            </Card>
          </Container>
          <Grid>
            <div style={{ position: 'absolute', bottom: 3, left: 15, color: '#697586' }}>
              <span>Scholae</span>
            </div>
            <div style={{ position: 'absolute', bottom: 3, right: 15, color: '#697586' }}>
              <span>by Innobs</span>
            </div>
          </Grid>
        </Box>
      </>
    );
  }
}

const mapStateToProps = state => {
  const loggedUser = state.auth.loggedUser ? state.auth.loggedUser : {};
  return {
    loggedUser,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    login: data => dispatch(login(data)),
    fetchSchool: data => dispatch(fetchSchoolService(data)),
    fetchCurrentBatchByYear: data => dispatch(fetchCurrentBatchByYearService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(LoginPage);
